import{expect,test}from"bun:test";
import{Database}from"bun:sqlite";
import Ajv from"ajv";
import fixture from"../../🧫️fixtures/🪶️sqlite/🔣️.json";
import lawsSchema from"../../🧫️fixtures/🪶️sqlite/🧬️schema/🔣️.json";
import nativeSchema from"../../🔣️.json";
import artifactSchema from"../../../🔣️.json";
import ioSchema from"../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🧬️schema/🔣️.json";
import childSchema from"../../../../../../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store/🪆️child/🧬️schema/🔣️.json";
import semioChildSchema from"../../../../../../../../../../../🗄️stdio/🗿️artifacts/🧿️semio/🏅️standards/🔖️v1/🪆️subsets/✉️base/🧬️schema/🪆️child/🔣️.json";
import * as owner from"../../🟦️.ts";
import{binary32,binary64,type Binary32,type Binary64}from"../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🔢️ieee754/🟦️.ts";
import{exportSqliteDatabase,importSqliteDatabase,type SqliteDatabase}from"../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts";
import type{ArtifactSqliteOptions}from"../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🧩️artifact/🟦️.ts";
type Geometry={kind:"box";width:Binary64;height:Binary64;depth:Binary64}|{kind:"frame";width:Binary64;height:Binary64;depth:Binary64;profile:Binary64}|{kind:"slab";width:Binary64;depth:Binary64;thickness:Binary64}|{kind:"mesh";positions:Binary32[];normals:Binary32[];indices:number[]}|{kind:"glb";url:string;extent:Binary64};
type Extra=Omit<owner.CurationSnapshot["stockExtra"][number],"geometry">&{geometry:Geometry};
type Snapshot=Omit<owner.CurationSnapshot,"stockExtra">&{stockExtra:Extra[]};
const own=owner;
function snapshot():Snapshot{const source=owner.parseCurationSnapshot(structuredClone(fixture.snapshot));return{...source,stockExtra:source.stockExtra.map(({geometry:g,...extra})=>({...extra,geometry:g.kind==="mesh"?{...g,positions:g.positions.map(binary32),normals:g.normals.map(binary32)}:g.kind==="glb"?{...g,extent:binary64(g.extent)}:g.kind==="slab"?{...g,width:binary64(g.width),depth:binary64(g.depth),thickness:binary64(g.thickness)}:g.kind==="frame"?{...g,width:binary64(g.width),height:binary64(g.height),depth:binary64(g.depth),profile:binary64(g.profile)}:{...g,width:binary64(g.width),height:binary64(g.height),depth:binary64(g.depth)}}))}}
const bytes=async(value:Snapshot)=>exportSqliteDatabase(await own.curationSnapshotToSqliteDatabase(value));
const restore=async(value:Uint8Array,options:ArtifactSqliteOptions={})=>own.curationSnapshotFromSqliteDatabase(await importSqliteDatabase(value),options);
test("Curation independent neutral schema admits all five complete persisted recipes",()=>{const validator=new Ajv({strict:false,validateFormats:false}).addSchema(ioSchema).addSchema(childSchema).addSchema(semioChildSchema).addSchema(artifactSchema).addSchema(nativeSchema);expect(validator.validate(lawsSchema,fixture)).toBe(true)});
test("Curation independent SQLite schema contains fourteen domain tables and explicit geometry widths",async()=>{const db=new Database(":memory:");try{db.run(await Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url)).text());expect(db.query("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name").all()).toEqual(["curation_box","curation_catalog","curation_curated","curation_document","curation_frame","curation_geometry","curation_glb","curation_mesh","curation_mesh_index","curation_mesh_normal","curation_mesh_position","curation_slab","curation_stock_extra","curation_typology_segment"].map(name=>({name})));expect(db.query("PRAGMA table_info(curation_box)").all().length).toBe(11);expect(db.query("PRAGMA table_info(curation_mesh_position)").all().length).toBe(6)}finally{db.close()}});
test("Curation public persisted facade exposes both semantic relational directions",()=>{expect(Object.hasOwn(owner,"curationSnapshotToSqliteDatabase")).toBe(true);expect(Object.hasOwn(owner,"curationSnapshotFromSqliteDatabase")).toBe(true)});
test("Curation queryable files retain all recipes ordered paths duplicate IDs and unresolved selections",async()=>{const expected=snapshot(),data=await bytes(expected),db=Database.deserialize(data,{safeIntegers:true});try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query("SELECT kind FROM curation_geometry ORDER BY id").all()).toEqual(["box","frame","slab","mesh","glb"].map(kind=>({kind})));expect(db.query("SELECT value FROM curation_mesh_index ORDER BY ordinal").all()).toEqual([{value:4294967295n},{value:0n},{value:0n}]);expect(await restore(data)).toEqual(expected)}finally{db.close()}});
for(const hex of fixture.binary64Words)test("Curation every dimension retains raw binary64 "+hex,async()=>{const expected=snapshot(),word={bits:BigInt("0x"+hex)};for(const row of expected.stockExtra){const g=row.geometry;if(g.kind==="mesh")continue;if(g.kind==="glb")g.extent=word;else{g.width=word;g.depth=word;if(g.kind==="slab")g.thickness=word;else{g.height=word;if(g.kind==="frame")g.profile=word}}}const db=Database.deserialize(await bytes(expected),{safeIntegers:true});try{const buffer=Buffer.alloc(8);buffer.writeBigUInt64BE(word.bits);const n=buffer.readDoubleBE(),kind=Number.isNaN(n)?"nan":n===Infinity?"positiveInfinity":n===-Infinity?"negativeInfinity":"finite";expect(db.query("SELECT width_bits,width_class FROM curation_box").get()).toEqual({width_bits:BigInt.asIntN(64,word.bits),width_class:kind});expect(await restore(new Uint8Array(db.serialize()))).toEqual(expected)}finally{db.close()}});
for(const hex of fixture.binary32Words)test("Curation every Mesh scalar retains raw binary32 "+hex,async()=>{const expected=snapshot(),word={bits:parseInt(hex,16)},g=expected.stockExtra[3]!.geometry;if(g.kind!=="mesh")throw Error("fixture Mesh required");g.positions=[word,word];g.normals=[word];const db=Database.deserialize(await bytes(expected),{safeIntegers:true});try{const buffer=Buffer.alloc(4);buffer.writeUInt32BE(word.bits);const n=buffer.readFloatBE(),kind=Number.isNaN(n)?"nan":n===Infinity?"positiveInfinity":n===-Infinity?"negativeInfinity":"finite";expect(db.query("SELECT value_bits,value_class FROM curation_mesh_position ORDER BY ordinal").all()).toEqual([{value_bits:BigInt(word.bits),value_class:kind},{value_bits:BigInt(word.bits),value_class:kind}]);expect(await restore(new Uint8Array(db.serialize()))).toEqual(expected)}finally{db.close()}});
test("Curation independent edits preserve relationships under arbitrary positive surrogate renumbering",async()=>{const expected=snapshot(),db=Database.deserialize(await bytes(expected));try{db.run("UPDATE curation_stock_extra SET id=id+100,name='renamed'");db.run("UPDATE curation_typology_segment SET stock_extra_id=stock_extra_id+100");db.run("UPDATE curation_geometry SET id=id+200,stock_extra_id=stock_extra_id+100");for(const table of["box","frame","slab","mesh","glb"])db.run("UPDATE curation_"+table+" SET geometry_id=geometry_id+200");db.run("UPDATE curation_mesh SET id=id+300");for(const table of["position","normal","index"])db.run("UPDATE curation_mesh_"+table+" SET mesh_id=mesh_id+300");db.run("UPDATE curation_catalog SET id=id+99");db.run("UPDATE curation_curated SET object_id='edited'");for(const row of expected.stockExtra)row.name="renamed";for(const row of expected.curated)row.objectId="edited";expect(await restore(new Uint8Array(db.serialize()))).toEqual(expected)}finally{db.close()}});
for(const[index,sql]of fixture.malformedSql.entries())test("Curation independent malformed semantic edit refuses "+index,async()=>{const db=Database.deserialize(await bytes(snapshot()));try{db.run("PRAGMA ignore_check_constraints=ON");db.run(sql);await expect(restore(new Uint8Array(db.serialize()))).rejects.toThrow()}finally{db.close()}});
test("Curation exact row count admits equality and refuses one below",async()=>{const expected=snapshot(),database=await own.curationSnapshotToSqliteDatabase(expected),rows=database.tables.reduce((sum,table)=>sum+table.rows.length,0);await expect(own.curationSnapshotToSqliteDatabase(expected,{maxRows:rows})).resolves.toBeDefined();await expect(own.curationSnapshotToSqliteDatabase(expected,{maxRows:rows-1})).rejects.toThrow()});
test("Curation caller byte ceilings bound actual scalar collections and UTF8 ownership",async()=>{const expected=snapshot(),db=await own.curationSnapshotToSqliteDatabase(expected);await expect(own.curationSnapshotFromSqliteDatabase(db,{maxValueBytes:1})).rejects.toThrow();await expect(exportSqliteDatabase(db,{maxFileBytes:fixture.control.tinyFileBytes})).rejects.toThrow();expected.stockExtra[0]!.name="😀".repeat(fixture.control.largeTextBytes);await expect(own.curationSnapshotToSqliteDatabase(expected,{maxValueBytes:fixture.control.maxOwnedBytes})).rejects.toThrow()});
for(const phase of["projectSnapshot","reconstructSnapshot"]as const)test("Curation cancellation interrupts "+phase+" inside known typology ownership",async()=>{const expected=snapshot();expected.stockExtra[0]!.typologyPath=Array.from({length:fixture.control.collectionLength},(_,index)=>String(index));const db=await own.curationSnapshotToSqliteDatabase(expected),controller=new AbortController();let reached=false;const options:ArtifactSqliteOptions={signal:controller.signal,onProgress:event=>{if(event.phase===phase&&event.completed>=256&&event.completed<event.total){reached=true;controller.abort()}}};await expect(phase==="projectSnapshot"?own.curationSnapshotToSqliteDatabase(expected,options):own.curationSnapshotFromSqliteDatabase(db,options)).rejects.toHaveProperty("kind","canceled");expect(reached).toBe(true);const initial=new AbortController();initial.abort();await expect(phase==="projectSnapshot"?own.curationSnapshotToSqliteDatabase(snapshot(),{signal:initial.signal}):own.curationSnapshotFromSqliteDatabase(db,{signal:initial.signal})).rejects.toHaveProperty("kind","canceled")});

test("Curation mandatory Kit child identity is literal for empty reserved and Unicode strings",async()=>{for(const identity of fixture.literalChildIds){const expected=snapshot();expected.catalog.childId=identity;expected.catalog.target.artifactId=identity;expect(await restore(await bytes(expected))).toEqual(expected)}});

test("Curation cancellation reaches the actual typed typology ordinal frontier",async()=>{const expected=snapshot(),length=fixture.control.collectionLength;expected.stockExtra[0]!.typologyPath=Array.from({length},(_,ordinal)=>String(ordinal));const database=await own.curationSnapshotToSqliteDatabase(expected),controller=new AbortController();let reached=false;await expect(own.curationSnapshotFromSqliteDatabase(database,{signal:controller.signal,onProgress:event=>{if(event.phase==="reconstructSnapshot"&&event.total===length&&event.completed>=256&&event.completed<length){reached=true;controller.abort()}}})).rejects.toHaveProperty("kind","canceled");expect(reached).toBe(true)});

test("Curation caller ownership budget admits cells separately and refuses oversized reconstruction lookups",async()=>{const expected=snapshot();expected.stockExtra[0]!.typologyPath=Array.from({length:fixture.control.collectionLength},()=>"");const database=await own.curationSnapshotToSqliteDatabase(expected),cellBytes=database.tables.reduce((sum,table)=>sum+table.rows.reduce((sum,row)=>sum+row.values.reduce<number>((sum,value)=>sum+(typeof value==="string"?Buffer.byteLength(value,"utf8"):value===null?0:value instanceof Uint8Array?value.byteLength:8),0),0),0);expect(cellBytes).toBeLessThan(fixture.control.maxOwnedBytes);const db=Database.deserialize(await exportSqliteDatabase(database));try{expect(db.query("SELECT COUNT(*) AS count FROM curation_typology_segment").get()).toEqual({count:fixture.control.collectionLength+2});expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"})}finally{db.close()}await expect(own.curationSnapshotFromSqliteDatabase(database,{maxValueBytes:fixture.control.maxOwnedBytes})).rejects.toThrow()});
test("Curation local Kit child aliases retain distinct literal target identities",async()=>{for(const pair of fixture.literalChildAliases){const expected=snapshot();expected.catalog.childId=pair.childId;expected.catalog.target.artifactId=pair.artifactId;expect(await restore(await bytes(expected))).toEqual(expected)}});

