test("Curation distinct logical child and addressed target have valid full physical SQLite ownership",async()=>{const validate=new Ajv({strict:true}).compile(distinctChildSchema);expect(validate(distinctChild)).toBe(true);expect(distinctChild.childId).not.toBe(distinctChild.artifactId);const expected=snapshot();expected.catalog.childId=distinctChild.childId;expected.catalog.target.artifactId=distinctChild.artifactId;expected.catalog.target.dialect={...distinctChild.dialect};const data=await bytes(expected),db=Database.deserialize(data,{safeIntegers:true});try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query("SELECT child_id,artifact_id,artifact_kind,standard,subset FROM curation_catalog").all()).toEqual([{child_id:distinctChild.childId,artifact_id:distinctChild.artifactId,artifact_kind:distinctChild.dialect.artifactKind,standard:distinctChild.dialect.standard,subset:distinctChild.dialect.subset}]);expect(await restore(new Uint8Array(db.serialize()))).toEqual(expected)}finally{db.close()}});
